const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.resolve(__dirname, '..');
const CSS_DIR = path.join(ROOT, 'public', 'css');

// Keep these lists in the same order as the links in layouts/main.ejs. The
// split around the shop's inline theme variables is intentional: it preserves
// the existing cascade while reducing render-blocking stylesheet requests.
const BUNDLES = Object.freeze({
  'storefront-listing-v1.css': ['storefront-catalog-shared-v1.css', 'storefront-catalog-shared-v2.css', 'storefront-owner-home-v21.css'],
  'storefront-pre-unified-v1.css': [
    'storefront-navbar-v1.css',
    'storefront-home-v1.css',
    'storefront-owner-home-v1.css',
    'storefront-mobile-v1.css',
    'storefront-catalog-v1.css',
    'storefront-auth-v1.css',
    'scroll-motion-v1.css',
    'storefront-navbar-main-v2.css',
    'storefront-navbar-main-v3.css',
    'storefront-announcement-width-v1.css',
    'storefront-theme-cohesion-v1.css',
    'storefront-music-unified-v1.css',
    'storefront-navbar-shared-v1.css',
    'main-service-strip-v1.css',
    'latest-orders-loop-v1.css',
  ],
  'storefront-pre-home-v1.css': [
    'storefront-navbar-v1.css',
    'storefront-home-v1.css',
    'storefront-owner-home-v1.css',
    'storefront-mobile-v1.css',
    'storefront-catalog-v1.css',
    'storefront-auth-v1.css',
    'scroll-motion-v1.css',
    'storefront-owner-home-v7.css',
    'storefront-navbar-main-v2.css',
    'storefront-owner-home-v20.css',
    'storefront-owner-home-v21.css',
    'storefront-owner-home-hero-v22.css',
    'storefront-owner-home-hero-v23.css',
    'storefront-category-images-v1.css',
    'storefront-category-gallery-cozy-v2.css',
    'storefront-section-chrome-v1.css',
    'storefront-navbar-main-v3.css',
    'latest-orders-loop-v1.css',
    'latest-orders-3d-v1.css',
    'storefront-announcement-width-v1.css',
    'storefront-home-compact-v1.css',
    'storefront-home-mobile-v1.css',
    'storefront-theme-cohesion-v1.css',
    'storefront-music-unified-v1.css',
    'storefront-navbar-shared-v1.css',
    'main-service-strip-v1.css',
  ],
  'storefront-post-unified-v1.css': [
    'storefront-navbar-cozy-v1.css',
    'storefront-navbar-cozy-v2.css',
    'storefront-mobile-header-cozy-shared-v1.css',
    'storefront-mobile-header-cozy-v3.css',
    'storefront-account-menu-cozy-v1.css',
    'storefront-account-menu-mobile-v1.css',
    'storefront-product-artwork-full-v1.css',
    'storefront-home-section-spacing-v1.css',
  ],
  'storefront-post-home-v1.css': [
    'storefront-navbar-cozy-v1.css',
    'storefront-navbar-cozy-v2.css',
    'storefront-mobile-header-cozy-shared-v1.css',
    'storefront-mobile-header-cozy-v3.css',
    'storefront-account-menu-cozy-v1.css',
    'storefront-account-menu-mobile-v1.css',
    'storefront-home-cozy-v1.css',
    'storefront-home-hero-cozy-v1.css',
    'storefront-product-artwork-full-v1.css',
    'storefront-home-section-spacing-v1.css',
  ],
  'storefront-home-popup-v1.css': [
    'storefront-welcome-popup-main-v2.css',
  ],
});

function bundleContents(files) {
  const parts = files.map((file) => {
    const sourcePath = path.join(CSS_DIR, file);
    if (!fs.existsSync(sourcePath)) throw new Error(`Missing CSS bundle source: ${sourcePath}`);
    // Keep generated assets byte-stable across Windows and Linux checkouts.
    // Source CSS may be checked out with CRLF on Windows, while the committed
    // bundles are LF; normalizing here prevents false stale-bundle failures.
    const source = fs.readFileSync(sourcePath, 'utf8').replace(/\r\n?/g, '\n').trimEnd();
    return `/* Source: ${file} */\n${source}`;
  });
  return `/* Generated by scripts/build-css-bundles.js; preserve source order. */\n${parts.join('\n\n')}\n`;
}

function checkCssBundles() {
  const staleFiles = [];
  for (const [output, sources] of Object.entries(BUNDLES)) {
    const outputPath = path.join(CSS_DIR, output);
    const expected = bundleContents(sources);
    if (!fs.existsSync(outputPath) || fs.readFileSync(outputPath, 'utf8').replace(/\r\n/g, '\n') !== expected) staleFiles.push(output);
  }
  return { ok: staleFiles.length === 0, staleFiles };
}

function buildCssBundles({ checkOnly = false } = {}) {
  if (checkOnly) {
    const result = checkCssBundles();
    if (!result.ok) throw new Error(`Generated storefront CSS is stale: ${result.staleFiles.join(', ')}. Run npm run build:css.`);
    return result;
  }
  for (const [output, sources] of Object.entries(BUNDLES)) {
    fs.writeFileSync(path.join(CSS_DIR, output), bundleContents(sources));
  }
  return { ok: true, files: Object.keys(BUNDLES) };
}

if (require.main === module) {
  const result = buildCssBundles({ checkOnly: process.argv.includes('--check') });
  console.log(result.ok ? `${process.argv.includes('--check') ? 'Verified' : 'Generated'} ${Object.keys(BUNDLES).length} storefront CSS bundles.` : 'CSS bundle check failed.');
}

module.exports = { BUNDLES, buildCssBundles, checkCssBundles };
